"use client";
import { ArtemisScope } from "./artemis-scope";
import View2 from "./components/content-sections/variants/03-capability-showcase";
const variants = {"capability-showcase":View2};
export interface ArtemisContentSectionsProps { className?: string; variant?: "capability-showcase"; }
export function ArtemisContentSections({ className, variant = "capability-showcase" }: ArtemisContentSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useRef, useSyncExternalStore } from "react";
import { motion, useInView, type Transition } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
const REDUCE_QUERY = "(prefers-reduced-motion: reduce)";
function subscribeReduce(onChange: () => void): () => void {
    const media = window.matchMedia(REDUCE_QUERY);
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
}
function useArtemisReduceAfterHydration(): boolean {
    return useSyncExternalStore(subscribeReduce, () => window.matchMedia(REDUCE_QUERY).matches, () => false);
}
const IN_VIEW = { once: true, margin: "-60px" } as const;
const HEADING_IN_VIEW = { once: true, amount: 0.4 } as const;
const BADGE_HIDDEN = { opacity: 0, filter: "blur(8px)", y: 8 };
const BADGE_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const BADGE_TRANSITION: Transition = { duration: 0.55, ease: ARTEMIS_EASE_OUT };
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "28%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: "0%" };
const WORD_STAGGER = 0.075;
const REDUCED_WORD_STAGGER = 0.0225;
function wordTransition(i: number): Transition {
    const delay = i * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", visualDuration: 0.48, bounce: 0, delay },
    };
}
function reducedWordTransition(i: number): Transition {
    return { duration: 0.25, ease: ARTEMIS_EASE_OUT, delay: i * REDUCED_WORD_STAGGER };
}
const LIST_HIDDEN = { opacity: 0, y: 16 };
const LIST_SHOWN = { opacity: 1, y: 0 };
const LIST_TRANSITION: Transition = { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.35 };
const CARD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: 24 };
const CARD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
function cardTransition(i: number): Transition {
    return { duration: 0.65, ease: ARTEMIS_EASE_OUT, delay: 0.12 + i * 0.1 };
}
const LINES: readonly (readonly string[])[] = [
    ["Made", "for", "the", "way"],
    ["your", "team", "works."],
];
const CHECKLIST = [
    "Shape ideas with your whole team",
    "Move from planning into production",
    "Keep every handoff clear and visible",
    "Adapt the system as the work changes",
] as const;
type Card = {
    readonly index: number;
    readonly left: string;
    readonly icon: "layers" | "workflow";
    readonly eyebrow: string;
    readonly title: string;
    readonly body: string;
    readonly label: string;
};
const CARDS: readonly Card[] = [
    {
        index: 0,
        left: "-0%",
        icon: "layers",
        eyebrow: "Shared workspace",
        title: "Plan together",
        body: "Turn loose ideas into clear plans without losing the context behind them.",
        label: "Explore shared planning",
    },
    {
        index: 1,
        left: "-100%",
        icon: "workflow",
        eyebrow: "Connected flows",
        title: "Keep work moving",
        body: "Connect the steps, owners, and approvals that carry work through delivery.",
        label: "Explore connected flows",
    },
];
function CardIcon({ icon }: {
    icon: Card["icon"];
}) {
    if (icon === "layers") {
        return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-4" aria-hidden="true">
        <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
        <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
        <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
      </svg>);
    }
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-workflow art:size-4" aria-hidden="true">
      <rect width="8" height="8" x="3" y="3" rx="2"/>
      <path d="M7 11v4a2 2 0 0 0 2 2h4"/>
      <rect width="8" height="8" x="13" y="13" rx="2"/>
    </svg>);
}
function CapabilityCard({ card, reduce }: {
    card: Card;
    reduce: boolean;
}) {
    return (<motion.article className="art:group art:flex art:h-full art:flex-col art:rounded-3xl art:border art:border-border art:bg-background art:p-3" initial={CARD_HIDDEN} whileInView={reduce ? undefined : CARD_SHOWN} viewport={IN_VIEW} transition={cardTransition(card.index)}>
      <div className="art:relative art:isolate art:h-64 art:overflow-hidden art:rounded-2xl art:@min-[1024px]/artemis:h-72">
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden">
          <img src="/assets/artemis/53d1b8e86d53a8e3341c.webp" alt="" width="1536" height="768" loading="lazy" decoding="async" className="art:absolute art:top-1/2 art:h-auto art:max-w-none art:-translate-y-1/2" style={{ width: "200%", left: card.left }}/>
        </div>
      </div>
      <div className="art:flex art:flex-col art:p-3 art:pb-2 art:pt-5 art:@min-[640px]/artemis:p-4 art:@min-[640px]/artemis:pb-3 art:@min-[640px]/artemis:pt-6">
        <div className="art:mb-3 art:flex art:items-center art:gap-2 art:text-muted-foreground">
          <span className="art:grid art:size-8 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted">
            <CardIcon icon={card.icon}/>
          </span>
          <span className="art:text-xs art:font-medium">
            {card.eyebrow}
          </span>
        </div>
        <h3 className="art:text-xl art:font-medium art:tracking-tight">
          {card.title}
        </h3>
        <p className="art:mt-2.5 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[1024px]/artemis:min-h-12">
          {card.body}
        </p>
        <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-card art:text-foreground art:hover:border-border art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:w-fit art:gap-2 art:h-9 art:rounded-full" aria-label={card.label} href="#" tabIndex={0}>
          {"Explore"}
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4 art:transition-transform art:duration-300 art:group-hover:translate-x-0.5 art:group-hover:-translate-y-0.5" aria-hidden="true">
            <path d="M7 7h10v10"/>
            <path d="M7 17 17 7"/>
          </svg>
        </motion.a>
      </div>
    </motion.article>);
}
export default function ContentSectionsCapabilityShowcase() {
    const reduce = useArtemisReduceAfterHydration();
    const headingRef = useRef<HTMLHeadingElement>(null);
    const headingInView = useInView(headingRef, HEADING_IN_VIEW);
    let wordIndex = 0;
    return (<>
      <section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
        <div className="art:mx-auto art:grid art:w-full art:max-w-7xl art:items-start art:gap-x-4 art:gap-y-10 art:@min-[1024px]/artemis:grid-cols-[1.35fr_1fr_1fr]">
          <div className="art:flex art:flex-col art:px-1 art:py-2 art:@min-[640px]/artemis:px-2 art:@min-[1024px]/artemis:min-h-[29rem] art:@min-[1024px]/artemis:py-5 art:@min-[1024px]/artemis:pr-8">
            <motion.span className="art:w-fit art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={BADGE_HIDDEN} whileInView={reduce ? undefined : BADGE_SHOWN} viewport={IN_VIEW} transition={BADGE_TRANSITION}>
              {"One connected system"}
            </motion.span>
            <h2 ref={headingRef} className="art:block art:mt-8 art:text-balance art:tracking-[-0.055em] art:@min-[1024px]/artemis:[&>span]:whitespace-nowrap art:text-4xl art:font-medium">
              {LINES.map((line, lineIndex) => (<span key={lineIndex} className="art:block">
                  {line.map((word, i) => {
                const index = wordIndex++;
                const last = i === line.length - 1;
                const shown = reduce ? { opacity: 1 } : WORD_SHOWN;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={headingInView ? shown : WORD_HIDDEN} transition={reduce ? reducedWordTransition(index) : wordTransition(index)}>
                        {word}
                        {last ? null : (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                            {"\u00A0"}
                          </span>)}
                      </motion.span>);
            })}
                </span>))}
            </h2>
            <motion.ul className="art:mt-12 art:space-y-3.5 art:@min-[1024px]/artemis:mt-auto" initial={LIST_HIDDEN} whileInView={reduce ? undefined : LIST_SHOWN} viewport={IN_VIEW} transition={LIST_TRANSITION}>
              {CHECKLIST.map((item) => (<li key={item} className="art:flex art:items-start art:gap-3 art:text-sm art:leading-6 art:text-muted-foreground">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-circle-check art:mt-0.5 art:size-5 art:shrink-0 art:text-foreground" aria-hidden="true">
                    <circle cx="12" cy="12" r="10"/>
                    <path d="m9 12 2 2 4-4"/>
                  </svg>
                  <span>
                    {item}
                  </span>
                </li>))}
            </motion.ul>
          </div>
          {CARDS.map((card) => (<CapabilityCard key={card.label} card={card} reduce={reduce}/>))}
        </div>
      </section>
    </>);
}
